'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), euro=n=>new Intl.NumberFormat('pt-PT',{style:'currency',currency:'EUR'}).format(n), uid=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join(''), now=()=>new Date().toISOString(), date=s=>new Date(s).toLocaleDateString('pt-PT',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}), clone=o=>JSON.parse(JSON.stringify(o));
const icons={projects:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',rules:'<path d="M4 7h16M4 17h16M8 4v6M16 14v6"/>',roadmap:'<path d="M6 3v18M6 5h12l-3 4 3 4H6"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">${icons[k]||icons.projects}</svg>`;
function initial(){const t=now();const p={id:uid(),code:'PRJ-001',name:'Portão de correr · Moradia',client:'João Martins',channel:'WhatsApp',demo:true,status:'Rascunho',created:t,request:'Bom dia! Precisava de um orçamento para um portão de correr, em aço, com 3 metros de largura e 1,8 metros de altura. Queria acabamento em cinzento antracite. Ainda não sei se pretendo incluir o motor. A instalação é em Sintra. Obrigado!',fields:{type:'Portão de correr',material:'Aço',width:'3',height:'1.8',quantity:'1',finish:'Cinzento antracite'},lines:[{id:uid(),desc:'Estrutura em perfil de aço',qty:22,unit:'m',price:8.5,source:'Estimativa de demonstração · confirmar perfis e comprimentos'},{id:uid(),desc:'Chapa de enchimento',qty:5.4,unit:'m²',price:32,source:'3,00 × 1,80 m · área bruta, sem perdas'},{id:uid(),desc:'Kit de ferragens e guia',qty:1,unit:'un',price:120,source:'Preço fictício · tabela de demonstração'},{id:uid(),desc:'Corte e soldadura',qty:8,unit:'h',price:28,source:'Estimativa de demonstração · validar horas'},{id:uid(),desc:'Preparação e pintura',qty:5.4,unit:'m²',price:22,source:'Uma face · confirmar processo e área tratada'},{id:uid(),desc:'Montagem no local',qty:4,unit:'h',price:28,source:'Estimativa de demonstração · acesso por confirmar'}],markup:25,vat:23,versions:[],files:[],memory:[{id:uid(),text:'Motorização ainda por decidir. Não incluída no rascunho.',kind:'Pendente',source:'Pedido inicial · WhatsApp (exemplo)',created:t},{id:uid(),text:'Dimensões indicadas: 3,00 m de largura × 1,80 m de altura. Aguardar validação no local.',kind:'Hipótese',source:'Pedido inicial · sem medição técnica',created:t},{id:uid(),text:'Acabamento pretendido: cinzento antracite. RAL exato por confirmar.',kind:'Pendente',source:'Pedido inicial · WhatsApp (exemplo)',created:t}],events:[{id:uid(),text:'Projeto de demonstração criado com pedido e custos fictícios.',source:'Forja · demonstração',created:t}]};return{schema:1,projects:[p],settings:{company:'A minha oficina',hour:28,markup:25,vat:23}}}
let state;if(globalThis.forjaPilot)state=globalThis.forjaPilot.initialState;else try{const saved=localStorage.getItem('forja-v1');state=saved?JSON.parse(saved):initial();if(state.schema!==1||!Array.isArray(state.projects))throw Error();}catch{state=initial()}
let view=globalThis.forjaPilot?'projects':'detail',tab='pedido',selected=state.projects[0]?.id,query='',memoryQuery='';
function project(){return state.projects.find(p=>p.id===selected)}
function persist(){if(globalThis.forjaPilot)return globalThis.forjaPilot.save(state);try{localStorage.setItem('forja-v1',JSON.stringify(state));return true}catch{toast('Não foi possível guardar neste navegador. Exporta uma cópia dos dados.');return false}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600)}
function dirty(p){if(p.status==='Aceite')p.status='Em revisão'}
function event(p,text,source='Registo manual'){p.events.unshift({id:uid(),text,source,created:now()})}
function calc(p){const cents=n=>Math.round((n+Number.EPSILON)*100)/100;const cost=cents(p.lines.reduce((a,l)=>a+cents(Number(l.qty)*Number(l.price)),0));const markup=cents(cost*Number(p.markup)/100);const subtotal=cents(cost+markup);const tax=cents(subtotal*Number(p.vat)/100);return{cost,markup,subtotal,tax,total:cents(subtotal+tax)}}
function badge(s){return `<span class="badge ${s==='Pendente'||s==='Rascunho'?'amber':s==='Hipótese'?'gray':''}">${esc(s)}</span>`}
function render(){if(globalThis.forjaPilot){renderPilotWorkspace();return;}if(!project()&&view==='detail')view='projects';const p=project();$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="mark">f</span>forja<span style="color:#8a9a7e">.</span></div><div class="brand-sub">ORÇAMENTOS COM MEMÓRIA</div><nav class="nav" aria-label="Principal">${[['projects','Projetos'],['rules','Regras de preço'],['roadmap','Próximas fases']].map(([id,l])=>`<button data-action="nav" data-view="${id}" class="${view===id||(id==='projects'&&view==='detail')?'active':''}">${icon(id)}${l}</button>`).join('')}</nav><div class="navlabel">EM FOCO</div>${state.projects.slice(0,3).map(p=>`<button class="ghost side-project" data-action="open" data-id="${p.id}">${esc(p.name)}</button>`).join('')}<div class="side-bottom"><div class="demo-chip"><span class="dot"></span> MVP · versão de teste</div><p>Do primeiro pedido<br>à última alteração.</p><div class="profile"><span class="avatar">OF</span><div>${esc(state.settings.company)}<br><span class="muted" style="font-size:10px">Espaço de trabalho</span></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Espaço de trabalho <span style="margin:0 10px">/</span> <b>${view==='detail'?`Projetos <span style="margin:0 10px;color:#aaa">/</span> ${p.code}`:({projects:'Projetos',rules:'Regras de preço',roadmap:'Próximas fases'}[view])}</b></div><div class="topright"><span class="hide-mobile">◉ &nbsp; Guardado neste navegador</span><button class="ghost small" data-action="help">Ajuda ↗</button></div></header><div class="workspace">${view==='detail'?detail(p):view==='projects'?projects():view==='rules'?rules():roadmap()}<div class="storage-banner"><span class="dot"></span> Dados guardados neste navegador. Exporta uma cópia para os conservar ou transferir.</div></div></main></div>`}
function detail(p){const counts=p.memory.filter(n=>n.kind==='Pendente').length;return `<button type="button" class="back-button no-print" data-action="nav" data-view="projects">← Voltar${globalThis.forjaPilot?' ao início':' aos projetos'}</button><div class="eyebrow">${esc(p.code)} &nbsp; / &nbsp; ${p.demo?'PROJETO DE DEMONSTRAÇÃO':'DOSSIER DE PROJETO'}</div><div class="heading"><div><h1>${esc(p.name)}</h1><p>${esc(p.client||'Cliente por indicar')} &nbsp;·&nbsp; ${esc(p.channel)} &nbsp;·&nbsp; ${badge(p.status)}</p></div><div class="heading-actions"><button data-action="new">+ Novo projeto</button><button class="primary" data-action="revision">↗ Registar alteração</button></div></div><nav class="tabbar" aria-label="Projeto">${[['pedido',globalThis.forjaPilot?'1. Pedido':'Pedido e dados',''],...(globalThis.forjaPilot?[]:[['interpretar','Interpretar ficheiros','']]),['orcamento',globalThis.forjaPilot?'2. Orçamento':'Orçamento',p.lines.length],['memoria','Memória do projeto',p.memory.length],['versoes','Versões',p.versions.length]].map(([k,l,c])=>`<button data-action="tab" data-tab="${k}" class="${tab===k?'active':''}">${l}${c!==''?`<span>${c}</span>`:''}</button>`).join('')}</nav><div class="detail-grid ${tab==='interpretar'?'interpret-layout':''}"><div class="stack">${tab==='interpretar'?analysisView(p):tab==='pedido'?requestView(p):tab==='orcamento'?quoteView(p):tab==='memoria'?(globalThis.forjaPilot&&typeof pilotMemoryView==='function'?pilotMemoryView(p):memoryView(p)):versionsView(p)}${globalThis.forjaPilot&&typeof pilotDetailExtras==='function'?pilotDetailExtras(p):''}</div>${globalThis.forjaPilot?`<aside class="stack pilot-aside">${summary(p)}</aside>`:legacyAside(p,counts)}</div>`}
function delta(p){const base=p.versions.filter(v=>v.accepted).at(-1)||p.versions.at(-1);if(!base)return '';const diff=Math.round((calc(p).subtotal-calc(base).subtotal)*100)/100;return `<div class="summary-line" style="background:#ffffff12;padding:10px;border-radius:5px;gap:7px"><span>Face à V${base.number}${base.accepted?' aceite':''}</span><strong>${diff>0?'+ ':''}${euro(diff)}</strong></div>`}
function summary(p){const t=calc(p);return `<section class="card summary"><div class="eyebrow">RASCUNHO ATUAL</div><div class="big-price" id="summary-total">${euro(t.subtotal)}</div><div class="smalltext">Valor de venda · sem IVA</div><hr><div class="summary-line"><span>Custo estimado</span><span id="summary-cost">${euro(t.cost)}</span></div><div class="summary-line"><span>Acréscimo sobre custo</span><span id="summary-markup">${p.markup}%</span></div><div class="summary-line"><span>IVA (${p.vat}%)</span><span id="summary-tax">${euro(t.tax)}</span></div><hr><div class="summary-line summary-grand-line"><span>Total com IVA</span><strong id="summary-grand">${euro(t.total)}</strong></div><div id="summary-delta">${delta(p)}</div>${globalThis.forjaPilot&&tab==='pedido'&&!p.lines.length?'<button data-pilot-goto-ai>Obter orçamento &nbsp; ↓</button>':`<button data-action="${tab==='orcamento'?'save-version':'tab'}" data-tab="orcamento">${tab==='orcamento'?'Guardar versão do orçamento':'Rever orçamento'} &nbsp; →</button>`}<div class="smalltext" style="text-align:center;margin-top:11px">${p.versions.length?`${p.versions.length} ${p.versions.length===1?'versão preservada':'versões preservadas'}`:'Ainda sem versões guardadas'}</div></section>`}
function requestView(p){return `<section class="card card-pad"><div class="card-title"><h2>O pedido do cliente</h2><button class="ghost small" data-action="edit-request">Editar pedido ↗</button></div><p class="request">${esc(p.request||'Ainda sem descrição. Adiciona o pedido do cliente.')}</p><div class="source"><span class="icon">↙</span> ${esc(p.channel)} · ${esc(p.client||'Cliente')}${p.contact?' · '+esc(p.contact):''}${p.place?' · obra: '+esc(p.place):''} ${p.demo?'· conteúdo fictício':''}</div></section>${globalThis.forjaPilot?``:`<section class="card card-pad"><div class="card-title"><h2>Dados para orçamentar</h2><button class="small" data-action="extract">Extrair do texto ↗</button></div><form id="fields-form"><div class="field-grid">${[['type','Tipo de trabalho','text'],['material','Material','text'],['width','Largura (m)','number'],['height','Altura (m)','number'],['quantity','Quantidade','number'],['finish','Acabamento','text']].map(([k,l,type])=>`<label>${l}<input class="field" name="${k}" type="${type}" ${type==='number'?'step="0.01" min="0.01"':''} value="${esc(p.fields[k])}" placeholder="Por confirmar"></label>`).join('')}</div><div class="extra-fields" id="extra-fields">${(p.extraFields||[]).map(extraFieldRow).join('')}</div><button type="button" class="small extra-add" data-add-field>+ Acrescentar dado</button><div class="section-foot"><span>Dados de trabalho · sujeitos a validação</span><button class="small primary" type="submit">Guardar dados</button></div></form><p class="smalltext muted" style="font-size:10px;margin-bottom:0">A extração usa regras simples para texto explícito. Não interpreta anexos nem recalcula linhas existentes.</p></section>`}<section class="card card-pad" id="anexos-card"><div class="card-title"><h2>Anexos do projeto</h2><span class="files-count${p.files.length?' has':''}">${p.files.length} ${p.files.length===1?'ficheiro':'ficheiros'}</span></div>${p.demo?blueprint():''}${p.files.map(f=>`<div class="file-row"><span class="file-icon">${esc(f.name.split('.').pop().toUpperCase().slice(0,5))}</span><div class="grow">${esc(f.name)}<small>${(f.size/1024).toFixed(0)} KB · ${date(f.created)}</small></div><button class="ghost small" data-action="file" data-id="${f.id}">Abrir</button>${globalThis.forjaPilot?`<button class="ghost small" data-action="file-remove" data-id="${f.id}" aria-label="Tirar ${esc(f.name)}">Tirar</button>`:''}</div>`).join('')}<label class="drop">${globalThis.forjaPilot?'<span class="drop-icon" aria-hidden="true"><svg viewBox="0 0 24 24" width="26" height="26" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5"/><path d="M8.5 17.5l2.5-5 2 3 1.5-2 1.5 4"/></svg></span><span class="drop-text"><strong>Adicionar fotos, PDFs ou desenhos</strong><small>Arrasta para aqui ou carrega para escolher. Também DXF e IFC.</small></span>':'＋ Adicionar fotos, esquiços ou documentos'}<input type="file" id="files" multiple accept="image/*,.pdf,.dwg,.dxf,.ifc,.txt" hidden></label><p class="muted smalltext" style="font-size:10px;margin-bottom:0">${globalThis.forjaPilot?'Tudo o que juntares aqui entra na análise quando carregares em “Obter orçamento”.':'Anexos guardados localmente. Abre “Interpretar ficheiros” para analisar um anexo.'}</p></section>`}
function blueprint(){return `<div class="blueprint"><svg viewBox="0 0 540 145" role="img" aria-label="Esquema ilustrativo de um portão de correr, 3 metros por 1,8 metros"><defs><pattern id="grid" width="15" height="15" patternUnits="userSpaceOnUse"><path d="M15 0H0V15" fill="none" stroke="#dfe6d5" stroke-width=".5"/></pattern></defs><rect width="540" height="145" fill="url(#grid)"/><g stroke="#6e8669" fill="none" stroke-width="1.2"><rect x="120" y="36" width="300" height="80"/><rect x="125" y="41" width="290" height="70"/><path d="M195 41v70m75-70v70m75-70v70M110 121h325M120 20h300M120 16v12m300-12v12M445 36v80m-4-80h8m-8 80h8"/><circle cx="160" cy="119" r="4"/><circle cx="380" cy="119" r="4"/></g><g fill="#607a59" font-family="monospace" font-size="10"><text x="250" y="15">3 000 mm</text><text x="455" y="80">1 800</text><text x="125" y="137" font-size="8">ELEVAÇÃO FRONTAL · SEM ESCALA</text></g></svg><small>Esquema ilustrativo do exemplo · não é desenho de fabrico</small></div>`}
function quoteView(p){const t=calc(p);return `<section class="card card-pad"><div class="card-title"><h2>Composição do orçamento</h2><div class="quote-actions no-print">${globalThis.forjaPilot?'<button class="small" data-pilot-autoprice>Preencher com o catálogo</button>':''}<button class="small" data-action="add-line">+ Adicionar linha</button></div></div><p class="smalltext muted no-print">Quantidades, custos unitários e origem de cada estimativa. Edita antes de guardar uma versão.</p><div class="table-scroll"><table class="quote-table"><thead><tr><th>ARTIGO / PROCESSO</th><th>QTD.</th><th>UN.</th><th>CUSTO €</th>${globalThis.forjaPilot?'<th class="no-print">CONFIANÇA</th>':''}<th>TOTAL</th><th class="no-print"></th></tr></thead><tbody>${p.lines.map(l=>`<tr><td><textarea class="desc" rows="1" aria-label="Descrição" data-line="${l.id}" data-key="desc">${esc(l.desc)}</textarea><small><button class="ghost line-src" data-action="line-source" data-id="${l.id}" title="Editar origem">↳ <span class="pilot-explain">${esc(l.source||'Fonte por indicar')}</span><span class="pilot-explain-alt">ver origem</span></button></small></td><td><input type="number" min="0" step="0.01" aria-label="Quantidade de ${esc(l.desc)}" data-line="${l.id}" data-key="qty" value="${l.qty}"></td><td><select aria-label="Unidade de ${esc(l.desc)}" data-line="${l.id}" data-key="unit">${['un','m','m²','m³','kg','h'].map(u=>`<option ${u===l.unit?'selected':''}>${u}</option>`).join('')}</select></td><td><input type="number" min="0" step="0.01" aria-label="Custo unitário de ${esc(l.desc)}" data-line="${l.id}" data-key="price" value="${l.price}"></td>${globalThis.forjaPilot?`<td class="no-print">${pilotConfidence(l)}</td>`:''}<td style="white-space:nowrap" data-total="${l.id}">${euro(Math.round(l.qty*l.price*100)/100)}</td><td class="no-print"><button class="remove" aria-label="Remover ${esc(l.desc)}" data-action="remove-line" data-id="${l.id}">×</button></td></tr>`).join('')}</tbody></table></div>${!p.lines.length?'<div class="empty">Adiciona materiais, processos e horas para começar.</div>':''}<div class="inline-settings no-print"><label>Acréscimo sobre custo <input id="markup" type="number" min="0" max="1000" step="0.1" value="${p.markup}"> %</label><label>IVA <input id="vat" type="number" min="0" max="100" step="0.1" value="${p.vat}"> %</label></div><p class="muted smalltext no-print" style="font-size:10px">Acréscimo de ${p.markup}% sobre o custo ≠ margem de ${p.markup}% sobre a venda. Taxa de IVA editável; confirma a aplicável.</p><div class="totals" id="totals">${totals(p)}</div><div class="section-foot no-print"><span>O rascunho pode mudar. As versões guardadas ficam preservadas.</span><button class="small" data-action="print">Imprimir / PDF ↗</button></div><div class="print-only"><p>Rascunho para revisão · ${esc(state.settings.company)} · ${new Date().toLocaleDateString('pt-PT')}</p><p>Valores e dados técnicos sujeitos a validação. Este documento contém a composição interna de custos.</p></div></section>`}
function totals(p){const t=calc(p);return `<div class="total-row"><span>Custo estimado</span><span>${euro(t.cost)}</span></div><div class="total-row"><span>Acréscimo (${p.markup}%)</span><span>${euro(t.markup)}</span></div><div class="total-row"><span>Venda sem IVA</span><strong>${euro(t.subtotal)}</strong></div><div class="total-row"><span>IVA (${p.vat}%)</span><span>${euro(t.tax)}</span></div><div class="total-row final"><span>Total com IVA</span><span>${euro(t.total)}</span></div>`}
function updateTotals(){const p=project(),t=calc(p);if($('#totals'))$('#totals').innerHTML=totals(p);if($('#summary-delta'))$('#summary-delta').innerHTML=delta(p);for(const [id,val] of Object.entries({'summary-total':euro(t.subtotal),'summary-cost':euro(t.cost),'summary-markup':p.markup+'%','summary-tax':euro(t.tax),'summary-grand':euro(t.total)})){if($('#'+id))$('#'+id).textContent=val}p.lines.forEach(l=>{const e=document.querySelector(`[data-total="${l.id}"]`);if(e)e.textContent=euro(Math.round(l.qty*l.price*100)/100)})}
function memoryView(p){return `<section class="card card-pad"><div class="card-title"><div><h2>O projeto não se esquece.</h2><p class="smalltext muted">Decisões, hipóteses e perguntas por resolver.</p></div><button class="small primary" data-action="add-memory">+ Registar</button></div><div class="memory-tools"><input class="field" id="memory-search" value="${esc(memoryQuery)}" placeholder="Procurar na memória…" aria-label="Procurar na memória"></div><div id="memory-items">${memoryItems(p)}</div></section>${fullTimeline(p)}`}
function memoryItems(p){return p.memory.filter(m=>(m.text+' '+m.source+' '+m.kind).toLowerCase().includes(memoryQuery.toLowerCase())).map(m=>`<article class="memory-item">${badge(m.kind)}<p>${esc(m.text)}</p><footer><span>↳ ${esc(m.source)}<br>${date(m.created)}${m.confirmed?' · Confirmado manualmente em '+date(m.confirmed):''}</span>${m.kind!=='Confirmado'?`<button class="small ghost" data-action="confirm-memory" data-id="${m.id}">Confirmar ✓</button>`:''}</footer></article>`).join('')||'<div class="empty">Nenhum registo encontrado.</div>'}
function legacyAside(p,counts){return `<aside class="stack">${summary(p)}${tab==='pedido'?`<section class="card card-pad"><div class="card-title"><h2>Antes de fechar</h2><span class="badge amber">${counts} pendentes</span></div><ul class="checks">${p.memory.filter(n=>n.kind==='Pendente').slice(0,4).map(n=>`<li><span class="check-icon">○</span><span>${esc(n.text)}</span></li>`).join('')||'<li>Sem pendentes registados. Confirma os dados antes de orçar.</li>'}</ul><button class="ghost small" style="padding-left:0;margin-top:12px;color:var(--green)" data-action="tab" data-tab="memoria">Abrir memória do projeto →</button></section>`:miniTimeline(p)}<div class="note">${p.demo?'<b>Exemplo fictício.</b> Preços e horas ilustrativos. Substitui-os pelos valores da oficina.':'<b>Revisão humana.</b> Confirma medidas, materiais, processos e preços antes de usar o orçamento.'}<br>${globalThis.forjaPilot?'Junta fotos, PDFs ou desenhos DXF/IFC e carrega em “Obter orçamento”, logo abaixo dos anexos.':'Leitores de imagem, PDF, DXF e IFC disponíveis em “Interpretar ficheiros”.'}</div></aside>`}
function miniTimeline(p){return `<section class="card card-pad"><div class="card-title"><h2>Últimos acontecimentos</h2></div><div class="timeline">${p.events.slice(0,3).map(e=>`<div class="event"><small>${date(e.created)}</small><p>${esc(e.text)}</p><div class="event-source">${esc(e.source)}</div></div>`).join('')}</div></section>`}
function fullTimeline(p){return `<section class="card card-pad"><div class="card-title"><h2>Histórico de atividade</h2><span class="muted smalltext">${p.events.length} registos</span></div><div class="timeline">${p.events.map(e=>`<div class="event"><small>${date(e.created)}</small><p>${esc(e.text)}</p><div class="event-source">${esc(e.source)}</div></div>`).join('')}</div></section>`}
function versionsView(p){return `<section class="card"><div class="card-pad"><div class="card-title"><h2>Versões preservadas</h2><button class="small primary" data-action="save-version">Guardar versão atual</button></div><p class="smalltext muted">Cada versão conserva os dados do pedido, as linhas de custo e as regras de preço. A aceitação é um registo manual do utilizador.</p></div>${p.versions.slice().reverse().map(v=>`<div class="version-row"><div><strong>V${v.number} · ${esc(v.label)}</strong><p>${date(v.created)} · ${v.lines.length} linhas ${v.accepted?'· Aceite em '+date(v.accepted):''}</p>${badge(v.accepted?'Aceite':'Guardada')}</div><div style="text-align:right"><strong>${euro(calc(v).subtotal)}</strong><p>sem IVA</p><button class="small ghost" data-action="view-version" data-id="${v.id}">Ver detalhe →</button></div></div>`).join('')||'<div class="empty">Ainda não guardaste uma versão.<br><br>Começa por rever o orçamento.</div>'}</section>`}
function projects(){let ps=state.projects.filter(p=>(p.name+' '+p.client+' '+p.code).toLowerCase().includes(query.toLowerCase()));return `<div class="eyebrow">A TUA OFICINA, ORGANIZADA</div><div class="heading"><div><h1>Todos os projetos</h1><p>Cada orçamento tem uma história. Mantém tudo no mesmo lugar.</p></div><button class="primary" data-action="new">+ Novo projeto</button></div><div class="stats"><section class="card stat"><span class="eyebrow">PROJETOS</span><strong>${state.projects.length.toString().padStart(2,'0')}</strong></section><section class="card stat"><span class="eyebrow">POR CONFIRMAR</span><strong>${state.projects.reduce((a,p)=>a+p.memory.filter(m=>m.kind==='Pendente').length,0).toString().padStart(2,'0')}</strong></section><section class="card stat"><span class="eyebrow">VERSÕES GUARDADAS</span><strong>${state.projects.reduce((a,p)=>a+p.versions.length,0).toString().padStart(2,'0')}</strong></section></div><div class="welcome"><div><h2>Menos procura. Mais trabalho feito.</h2><p>Experimenta o projeto de demonstração: revê os custos, guarda uma versão<br>e regista uma alteração do cliente.</p></div><button data-action="demo">Explorar exemplo →</button></div><div class="toolbar"><input class="field search" id="project-search" placeholder="Procurar projeto ou cliente…" value="${esc(query)}" aria-label="Procurar projetos"><div><button class="small ghost" data-action="export">Exportar cópia ↓</button><button class="small ghost" data-action="import">Importar cópia ↑</button></div></div><div class="card table-scroll"><table class="project-list"><thead><tr><th>Projeto / Cliente</th><th>Estado</th><th>Valor sem IVA</th><th>Memória</th><th></th></tr></thead><tbody id="project-rows">${projectRows(ps)}</tbody></table>${!ps.length?'<div class="empty">Nenhum projeto encontrado.</div>':''}</div>`}
function projectRows(ps){return ps.map(p=>`<tr data-action="open" data-id="${p.id}" tabindex="0"><td><strong>${esc(p.name)}</strong><span class="muted">${esc(p.client||'Sem cliente')} · ${p.code}${p.demo?' · Demo':''}</span></td><td>${badge(p.status)}</td><td>${euro(calc(p).subtotal)}</td><td>${p.memory.length} registos</td><td><button class="ghost small" aria-label="Abrir ${esc(p.name)}">→</button></td></tr>`).join('')}
function rules(){return `<div class="eyebrow">CONFIGURAÇÃO DA OFICINA</div><div class="heading"><div><h1>O teu trabalho. Os teus preços.</h1><p>Valores base para novos projetos. Os projetos existentes mantêm as suas regras.</p></div></div><div class="detail-grid"><section class="card card-pad"><form id="rules-form"><div class="card-title"><h2>Regras de preço</h2><span class="badge gray">Editável</span></div><div class="field-grid"><label class="full">Nome da oficina<input class="field" name="company" required maxlength="80" value="${esc(state.settings.company)}"></label><label>Custo de mão de obra (€/h)<input class="field" name="hour" type="number" min="0" step="0.01" required value="${state.settings.hour}"></label><label>Acréscimo sobre custo (%)<input class="field" name="markup" type="number" min="0" max="1000" step="0.1" required value="${state.settings.markup}"></label><label>IVA padrão (%)<input class="field" name="vat" type="number" min="0" max="100" step="0.1" required value="${state.settings.vat}"></label></div><p class="smalltext muted">O custo por hora é usado ao adicionar linhas com unidade “h”. A taxa de IVA deve ser confirmada para cada trabalho.</p><div class="section-foot"><span>Acréscimo aplicado sobre o custo total.</span><button class="primary" type="submit">Guardar regras</button></div></form></section><aside class="stack"><div class="card card-pad"><h2>Como calculamos</h2><p class="smalltext muted">Custo = soma de quantidade × custo unitário, arredondada por linha.<br><br>Venda sem IVA = custo + acréscimo.<br><br>Total = venda sem IVA + IVA.</p><div class="history-diff">100 € de custo + 25% de acréscimo = 125 € de venda sem IVA.</div></div><div class="note">Os valores iniciais são exemplos. Não são preços de mercado nem regras técnicas validadas.</div></aside></div>`}
function roadmap(){return `<div class="eyebrow">VISÃO DO PRODUTO</div><div class="heading"><div><h1>Começar útil. Evoluir com provas.</h1><p>O núcleo é a orçamentação. A memória acompanha cada fase.</p></div></div><div class="roadmap">${[['01','Já podes experimentar','Pedidos + orçamento + memória','Pedidos em texto, dados editáveis, anexos locais, cálculo por linhas, decisões, extras e versões preservadas.','MVP navegável'],['02','Beta disponível','Leitura de ficheiros','OCR de imagens e PDF, comprimentos e áreas em DXF, elementos e quantidades declaradas em IFC. Cada resultado exige revisão antes de entrar no orçamento.','Leitores locais'],['03','Fase posterior','Da ideia ao desenho técnico','Usar fotos, esquiços e medidas confirmadas para preparar desenho técnico editável. Revisão técnica antes de fabrico.','Por desenvolver']].map(([n,k,t,d,b])=>`<section class="card card-pad"><div class="eyebrow">FASE ${n} · ${k}</div><h2 style="font-size:22px;line-height:1.4">${t}</h2><p>${d}</p>${badge(b)}</section>`).join('')}</div><section class="card card-pad" style="margin-top:25px"><h2>O que esta versão faz realmente</h2><p class="smalltext muted">Os cálculos, a edição, os anexos, as versões e a memória funcionam no navegador. A extração de pedidos usa regras simples. Imagens usam OCR; DXF fornece geometria suportada; IFC fornece elementos e quantidades declaradas. Não há interpretação visual por IA, leitura DWG/RVT direta, geração CAD, sincronização entre dispositivos ou envio ao cliente.</p></section>`}
function modal(html){$('#modal').innerHTML=html;$('#modal').showModal();$('#modal').querySelectorAll('textarea').forEach(t=>{const fit=()=>{t.style.height='auto';t.style.height=Math.min(t.scrollHeight+4,Math.round(innerHeight*.6))+'px'};fit();t.addEventListener('input',fit)})}
function closeModal(){$('#modal').close()}
function modalHead(title,desc=''){return `<div class="modal-head"><h2>${title}</h2><button class="ghost small" data-action="close" aria-label="Fechar">×</button></div>${desc?`<p>${desc}</p>`:''}`}
function buttons(label){return `<div class="actions"><button type="button" data-action="close">Cancelar</button><button class="primary" type="submit">${label}</button></div>`}
function newProject(){modal(`${modalHead(globalThis.forjaPilot?'Novo orçamento':'Um novo projeto','Começa pelo pedido. O resto ganha forma aqui.')}<form id="new-form"><label>Nome do projeto<input class="field" name="name" required maxlength="100" placeholder="Ex.: Guarda de escada · Moradia"></label><label>Cliente<input class="field" name="client" required maxlength="100" placeholder="Nome do cliente"></label><label>Origem do pedido<select class="field" name="channel"><option>WhatsApp</option><option>Email</option><option>Chamada</option><option>Visita ao local</option><option>Outro</option></select></label><label>Pedido original<textarea class="field" name="request" ${globalThis.forjaPilot?'':'required'} placeholder="Cola o pedido do cliente, incluindo as medidas que já tens…"></textarea></label>${globalThis.forjaPilot?'<label>Desenho em PDF (opcional)<input class="field" name="drawing" type="file" accept=".pdf,application/pdf"></label>':''}${buttons(globalThis.forjaPilot?'Criar orçamento':'Criar projeto →')}</form>`)}
function addMemory(){modal(`${modalHead('Registar na memória','Guarda o que sabes e distingue-o do que falta confirmar.')}<form id="memory-form"><label>Registo<textarea class="field" name="text" required></textarea></label><label>Estado<select class="field" name="kind"><option>Pendente</option><option>Hipótese</option><option>Confirmado</option></select></label><label>Fonte / quem confirmou<input class="field" name="source" required placeholder="Ex.: Chamada com o cliente, 1 nov."></label>${buttons('Guardar registo')}</form>`)}
function revision(){modal(`${modalHead('Registar alteração','A versão anterior fica preservada. A alteração gera um pendente para reveres o orçamento.')}<form id="revision-form"><label>O que mudou?<textarea class="field" name="text" required placeholder="Ex.: O cliente pediu 3,5 m de largura e motorização."></textarea></label><label>Fonte do pedido<input class="field" name="source" required placeholder="Ex.: WhatsApp do cliente, hoje"></label><div class="note" style="margin-top:18px">Os custos não são alterados automaticamente. Revê as quantidades e adiciona os extras antes de guardar uma nova versão.</div>${buttons('Registar e rever orçamento')}</form>`)}
function snapshot(p,label){return{id:uid(),number:p.versions.length+1,label,created:now(),lines:clone(p.lines),markup:p.markup,vat:p.vat,fields:clone(p.fields),request:p.request,client:p.client,memory:clone(p.memory),accepted:null}}
function saveVersion(){const p=project();if(!p.lines.length){toast('Adiciona pelo menos uma linha ao orçamento.');return}modal(`${modalHead('Guardar versão do orçamento','As linhas, preços, dados e notas atuais ficam preservados.')}<form id="version-form"><label>Nome desta versão<input class="field" name="label" required value="Versão ${p.versions.length+1}"></label><div class="history-diff">Venda sem IVA: <b>${euro(calc(p).subtotal)}</b></div>${buttons('Guardar versão')}</form>`)}
function viewVersion(id){const p=project(),v=p.versions.find(v=>v.id===id),t=calc(v),prev=p.versions.find(x=>x.number===v.number-1);modal(`${modalHead('V'+v.number+' · '+esc(v.label),date(v.created))}<div class="modal-list">${v.accepted?`<div class="note">Aceitação registada manualmente: ${date(v.accepted)}<br>${esc(v.acceptSource)}</div>`:''}${prev?`<div class="history-diff">Diferença face à V${prev.number}: <b>${euro(t.subtotal-calc(prev).subtotal)}</b> sem IVA</div>`:''}<table class="project-list"><thead><tr><th>Artigo</th><th>Custo</th></tr></thead><tbody>${v.lines.map(l=>`<tr><td>${esc(l.desc)}<p class="muted" style="font-size:10px">${l.qty} ${esc(l.unit)} × ${euro(l.price)}<br>${esc(l.source)}</p></td><td>${euro(Math.round(l.qty*l.price*100)/100)}</td></tr>`).join('')}</tbody></table><div class="totals">${totals(v)}</div><p class="smalltext muted">Dados preservados: ${Object.entries(v.fields).filter(([k,val])=>val).map(([k,val])=>esc(({type:'Trabalho',material:'Material',width:'Largura (m)',height:'Altura (m)',quantity:'Quantidade',finish:'Acabamento'}[k])+': '+val)).join(' · ')}</p></div><div class="actions"><button data-action="close">Fechar</button>${!v.accepted?`<button class="primary" data-action="accept-version" data-id="${id}">Registar aceitação</button>`:''}</div>`)}
function extract(){const p=project(),s=p.request.toLowerCase(),f=p.fields,found=[];const set=(k,val)=>{if(!f[k]&&val){f[k]=val;found.push(k)}};const types=['portão de correr','portão','guarda','corrimão','escada','grade'];set('type',types.find(x=>s.includes(x)));set('material',['aço inoxidável','inox','aço','alumínio','ferro'].find(x=>s.includes(x)));const toM=(v,u)=>String(Number(v.replace(',','.'))/(u==='mm'?1000:u==='cm'?100:1));const w=s.match(/(\d+(?:[.,]\d+)?)\s*(mm|cm|metros?|m)\s*(?:de\s+)?largura/),h=s.match(/(\d+(?:[.,]\d+)?)\s*(mm|cm|metros?|m)\s*(?:de\s+)?altura/);if(w)set('width',toM(w[1],w[2]));if(h)set('height',toM(h[1],h[2]));if(found.length){p.memory.unshift({id:uid(),kind:'Hipótese',text:'Campos sugeridos a partir do texto: '+found.map(k=>({type:'tipo',material:'material',width:'largura',height:'altura'}[k])).join(', ')+'. Confirmar antes de usar.',source:'Extração por regras · pedido original',created:now()});event(p,'Extração de texto preencheu '+found.length+' campos vazios.','Regras de extração');persist();render();toast('Campos preenchidos. Confirma os valores extraídos.')}else toast('Sem novos campos explícitos detetados. Preenche ou revê manualmente.')}
let dbPromise;function db(){return dbPromise??=new Promise((resolve,reject)=>{const r=indexedDB.open('forja-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function filePut(id,blob){if(globalThis.forjaPilot)return globalThis.forjaPilot.putFile(id,blob);const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').put(blob,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function fileGet(id){if(globalThis.forjaPilot)return globalThis.forjaPilot.getFile(id);const d=await db();return new Promise((resolve,reject)=>{const r=d.transaction('files').objectStore('files').get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function addFiles(files){const p=project();for(const f of files){if(f.size>20*1024*1024){toast('Máximo de 20 MB por ficheiro: '+f.name);continue}if(globalThis.forjaPilot&&/\.(dwg|rvt)$/i.test(f.name)){toast(/\.dwg$/i.test(f.name)?'DWG não é lido diretamente: no AutoCAD, guarda como DXF e junta esse ficheiro.':'RVT não é lido diretamente: no Revit, exporta para IFC e junta esse ficheiro.');continue}try{const id=uid();const out=await filePut(id,f);p.files.push({id,name:f.name,type:out?.type||f.type,size:out?.size||f.size,created:now()});event(p,'Anexo adicionado: '+f.name,'Upload manual');if(globalThis.forjaPilot&&/\.(dxf|ifc)$/i.test(f.name)&&typeof readDrawingQuietly==='function')await readDrawingQuietly(p,f,id)}catch(err){toast(globalThis.forjaPilot&&err?.message?err.message:'Não foi possível guardar o anexo neste navegador.')}}persist();render()}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function exportData(){toast('A preparar cópia com os anexos…');try{const attachments={};for(const p of state.projects)for(const f of p.files){const blob=await fileGet(f.id);if(!blob)throw Error('Falta um anexo: '+f.name);attachments[f.id]=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob)})}download(new Blob([JSON.stringify({format:'forja-backup-v1',exported:now(),state,attachments})],{type:'application/json'}),'forja-copia-'+new Date().toISOString().slice(0,10)+'.json');toast('Cópia exportada com projetos e anexos.')}catch(e){toast('Falha na exportação: '+e.message)}}
function validState(s){if(s?.schema!==1||!Array.isArray(s.projects)||!s.settings||typeof s.settings.company!=='string')return false;const num=(n,max=1e9)=>typeof n==='number'&&Number.isFinite(n)&&n>=0&&n<=max;const txt=x=>typeof x==='string';const safeid=x=>txt(x)&&/^[a-f0-9-]{16,50}$/.test(x);const line=l=>safeid(l.id)&&txt(l.desc)&&txt(l.unit)&&txt(l.source)&&num(l.qty)&&num(l.price);const quote=q=>Array.isArray(q.lines)&&q.lines.every(line)&&num(q.markup,1000)&&num(q.vat,100);const memory=m=>safeid(m.id)&&txt(m.text)&&txt(m.source)&&['Pendente','Hipótese','Confirmado'].includes(m.kind)&&txt(m.created);return num(s.settings.hour)&&num(s.settings.markup,1000)&&num(s.settings.vat,100)&&s.projects.every(p=>safeid(p.id)&&txt(p.name)&&txt(p.code)&&/^PRJ-[0-9]+$/.test(p.code)&&txt(p.client)&&txt(p.channel)&&txt(p.status)&&txt(p.request)&&txt(p.created)&&p.fields&&['type','material','width','height','quantity','finish'].every(k=>txt(p.fields[k]))&&quote(p)&&Array.isArray(p.memory)&&p.memory.every(memory)&&Array.isArray(p.events)&&p.events.every(e=>safeid(e.id)&&txt(e.text)&&txt(e.source)&&txt(e.created))&&Array.isArray(p.versions)&&p.versions.every(v=>quote(v)&&safeid(v.id)&&txt(v.label)&&txt(v.created)&&num(v.number)&&v.fields)&&Array.isArray(p.files)&&p.files.every(f=>safeid(f.id)&&txt(f.name)&&txt(f.type)&&num(f.size)&&txt(f.created)))}
async function importFile(f){try{if(f.size>100*1024*1024)throw Error('A cópia excede 100 MB.');const data=JSON.parse(await f.text());if(data.format!=='forja-backup-v1'||!validState(data.state)||!data.attachments)throw Error('Formato de cópia inválido.');for(const p of data.state.projects)for(const file of p.files){const a=data.attachments[file.id];if(typeof a!=='string'||!/^data:[^,]*;base64,/.test(a))throw Error('Anexo inválido ou em falta.')}window.pendingImport=data;modal(`${modalHead('Importar cópia','Esta operação substitui os projetos deste navegador pelos da cópia. Exporta primeiro os dados atuais se os quiseres conservar.')}<div class="history-diff">${data.state.projects.length} projetos · cópia de ${esc(date(data.exported))}</div><div class="actions"><button data-action="close">Cancelar</button><button class="primary" data-action="confirm-import">Substituir e importar</button></div>`)}catch(e){toast(e.message)}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,p=project(),id=b.dataset.id;
if(a==='nav'){view=b.dataset.view;query='';render()}
if(a==='open'){selected=id;view='detail';tab='pedido';memoryQuery='';render()}
if(a==='tab'){tab=b.dataset.tab;if(typeof analysisPreviewHTML!=='undefined')analysisPreviewHTML='';render();if(tab==='interpretar')restoreAnalysisPreview()}
if(a==='close')closeModal();
if(a==='new')newProject();
if(a==='demo'){let demo=state.projects.find(p=>p.demo);if(!demo){demo=initial().projects[0];demo.code=nextCode();state.projects.push(demo);persist()}selected=demo.id;view='detail';tab='pedido';render()}
if(a==='edit-request')modal(`${modalHead('Editar pedido','Preserva a intenção do cliente. Usa “Registar alteração” para pedidos posteriores.')}<form id="request-form"><label>Pedido<textarea class="field" name="request" required>${esc(p.request)}</textarea></label>${buttons('Guardar pedido')}</form>`);
if(a==='extract')extract();
if(a==='revision')revision();
if(a==='add-memory')addMemory();
if(a==='confirm-memory'){const m=p.memory.find(m=>m.id===id);modal(`${modalHead('Confirmar informação','Regista de onde veio a confirmação.')}<p>${esc(m.text)}</p><form id="confirm-form" data-id="${id}"><label>Informação confirmada<textarea class="field" name="text" required>${esc(m.text)}</textarea></label><label>Fonte / quem confirmou<input class="field" name="source" required placeholder="Ex.: Cliente por chamada, hoje"></label>${buttons('Confirmar e guardar')}</form>`)}
if(a==='add-line')modal(`${modalHead('Adicionar custo','Introduz um material, processo ou serviço.')}<form id="line-form">${globalThis.forjaPilot?pilotCatalogSelect():''}<label>Descrição<input class="field" name="desc" required placeholder="Ex.: Corte e soldadura"></label><div class="field-grid"><label>Quantidade<input class="field" name="qty" type="number" min="0.01" step="0.01" required value="1"></label><label>Unidade<select class="field" name="unit" id="line-unit"><option>un</option><option>m</option><option>m²</option><option>m³</option><option>kg</option><option>h</option></select></label><label>Custo unitário (€)<input class="field" name="price" id="line-price" type="number" min="0" step="0.01" ${globalThis.forjaPilot?'placeholder="Vazio: usa o catálogo"':'required placeholder="0,00"'}></label></div><label>Fonte / justificação<input class="field" name="source" ${globalThis.forjaPilot?'placeholder="Vazio: usa o catálogo"':'required placeholder="Ex.: Tabela do fornecedor, referência 123"'}></label>${buttons('Adicionar ao orçamento')}</form>`);
if(a==='remove-line'){dirty(p);const l=p.lines.find(l=>l.id===id);p.lines=p.lines.filter(l=>l.id!==id);event(p,'Linha removida do rascunho: '+l.desc);persist();render()}
if(a==='line-source'){const l=p.lines.find(l=>l.id===id),parts=String(l.source||'').split(/\s+·\s+|\n+/).map(x=>x.trim()).filter(Boolean),warn=/confirmar|validar|estimativa|propost|por indicar|sem artigo/i,math=/[=×x*+]\s*\d|\d\s*[=×*+]/;modal(`${modalHead('Origem da estimativa')}<div class="origin-view"><p class="origin-line">${esc(l.desc||'Linha sem descrição')}</p><div class="origin-figures"><div><small>Quantidade</small><strong>${esc((Number(l.qty)||0).toLocaleString('pt-PT',{maximumFractionDigits:3}))} ${esc(l.unit||'')}</strong></div><div><small>Custo unitário</small><strong>${euro(Number(l.price)||0)}</strong></div><div class="origin-total"><small>Total da linha</small><strong>${euro(Math.round((Number(l.qty)||0)*(Number(l.price)||0)*100)/100)}</strong></div></div><div class="origin-source"><small>De onde vem</small>${parts.length?`<ul>${parts.map(x=>`<li class="${warn.test(x)?'origin-warn':math.test(x)?'origin-math':''}">${warn.test(x)?'<span class="origin-chip">A confirmar</span>':''}${esc(x)}</li>`).join('')}</ul>`:'<p class="origin-empty"><span class="origin-chip">A confirmar</span>Fonte por indicar. Diz de onde vem este valor.</p>'}</div></div><details class="origin-edit"${parts.length?'':' open'}><summary>Editar origem</summary><form id="source-form" data-id="${id}"><textarea class="field" name="source" rows="4" required aria-label="Origem da estimativa">${esc(l.source)}</textarea>${buttons('Guardar origem')}</form></details>`);$('#modal').querySelector('.origin-edit')?.addEventListener('toggle',e=>{const t=e.target.querySelector('textarea');if(e.target.open&&t){t.dispatchEvent(new Event('input'));t.focus()}})}
if(a==='save-version')saveVersion();
if(a==='view-version')viewVersion(id);
if(a==='accept-version'){modal(`${modalHead('Registar aceitação','Confirma apenas se o cliente aceitou esta versão. Este registo não envia mensagens.')}<form id="accept-form" data-id="${id}"><label>Fonte da aceitação<input class="field" name="source" required placeholder="Ex.: Email do cliente, 1 nov."></label>${buttons('Registar aceitação')}</form>`)}
if(a==='print'){tab='orcamento';render();window.print()}
if(a==='file-remove'){const f=p.files.find(f=>f.id===id);if(!f)return;if(!confirm('Tirar o anexo “'+f.name+'” deste pedido?'))return;p.files=p.files.filter(x=>x.id!==id);if(p.analyses)p.analyses=p.analyses.filter(x=>x.fileId!==id);event(p,'Anexo retirado: '+f.name,'Oficina');persist();render();try{if(globalThis.forjaPilot?.deleteFile&&await globalThis.forjaPilot.flush())await globalThis.forjaPilot.deleteFile(id)}catch{}toast('Anexo retirado.');return}if(a==='file'){try{const f=p.files.find(f=>f.id===id),blob=await fileGet(id);if(!blob)throw Error();download(blob,f.name)}catch{toast('Anexo indisponível neste navegador. Importa a cópia que o contém.')}}
if(a==='help')modal(`${modalHead('Experimenta a Forja')}<ol class="smalltext" style="line-height:2.1;padding-left:20px"><li>Abre o exemplo ou cria um projeto com um pedido.</li><li>Revê os dados e adiciona os anexos.</li><li>Edita custos e guarda a primeira versão.</li><li>Regista uma alteração do cliente e ajusta o orçamento.</li><li>Consulta decisões, pendentes e versões anteriores.</li></ol><div class="note">A extração de pedidos é baseada em regras de texto. Os leitores extraem OCR, geometria DXF e quantidades IFC. Não há interpretação visual por IA. Os dados ficam apenas neste navegador; usa a cópia de segurança para os transferir.</div><div class="actions"><button class="primary" data-action="close">Vamos a isso</button></div>`);
if(a==='export')await exportData();
if(a==='import'){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=()=>input.files[0]&&importFile(input.files[0]);input.click()}
if(a==='confirm-import'){const data=window.pendingImport;if(!data)return;try{for(const [id,value] of Object.entries(data.attachments)){const comma=value.indexOf(','),mime=value.slice(5,value.indexOf(';')),raw=atob(value.slice(comma+1)),bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));await filePut(id,new Blob([bytes],{type:mime}))}state=data.state;persist();selected=state.projects[0]?.id;view='projects';closeModal();render();window.pendingImport=null;toast('Cópia importada.')}catch{toast('Não foi possível importar todos os anexos. Os projetos atuais foram preservados.')}}
});
function nextCode(){return 'PRJ-'+String(Math.max(0,...state.projects.map(p=>Number(p.code.replace('PRJ-',''))||0))+1).padStart(3,'0')}
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(form.id==='analysis-apply-form')return;const f=new FormData(form),p=project();if(form.id==='new-form'){const drawing=globalThis.forjaPilot&&f.get('drawing');const np={id:uid(),code:nextCode(),name:f.get('name').trim(),client:f.get('client').trim(),channel:f.get('channel'),request:f.get('request').trim(),created:now(),demo:false,status:'Rascunho',fields:{type:'',material:'',width:'',height:'',quantity:'1',finish:''},lines:[],markup:state.settings.markup,vat:state.settings.vat,versions:[],memory:[{id:uid(),kind:'Pendente',text:'Validar medidas, especificações e condições de montagem antes de fechar o orçamento.',source:'Verificação inicial do projeto',created:now()}],files:[],events:[]};if(!np.name||!np.client||(!np.request&&!drawing?.size)){toast(globalThis.forjaPilot?'Indica o nome, o cliente e o pedido ou desenho.':'Preenche nome, cliente e pedido.');return}event(np,'Projeto criado. Pedido original registado.',np.channel);state.projects.push(np);selected=np.id;view='detail';tab='pedido';closeModal();persist();render();if(drawing?.size){if(globalThis.forjaPilot){await addFiles([drawing]);render();toast('Orçamento criado. Quando o pedido estiver completo, carrega em Obter orçamento, logo abaixo dos anexos.')}else await runAnalysis(drawing)}else toast(globalThis.forjaPilot?'Orçamento criado. Junta anexos se tiveres e carrega em Obter orçamento, logo abaixo dos anexos.':'Projeto criado. Podes extrair os dados do texto.');return}
if(form.id==='rules-form'){state.settings={company:f.get('company').trim(),hour:Number(f.get('hour')),markup:Number(f.get('markup')),vat:Number(f.get('vat'))};persist();render();toast('Regras guardadas para novos projetos.');return}
if(form.id==='fields-form'){const before=clone(p.fields);for(const k of Object.keys(p.fields))p.fields[k]=f.get(k);const changed=Object.keys(p.fields).filter(k=>before[k]!==p.fields[k]);const labels=f.getAll('extra-label'),values=f.getAll('extra-value');const extras=labels.map((l,i)=>({label:String(l).trim().slice(0,80),value:String(values[i]||'').trim().slice(0,300)})).filter(x=>x.label||x.value).slice(0,100);if(JSON.stringify(extras)!==JSON.stringify(p.extraFields||[])){dirty(p);event(p,'Outros dados: '+(extras.length?extras.map(x=>(x.label||'sem nome')+': '+(x.value||'por indicar')).join('; '):'removidos'));p.extraFields=extras}if(changed.length)dirty(p);if(changed.length)event(p,'Dados alterados: '+changed.map(k=>({type:'tipo',material:'material',width:'largura',height:'altura',quantity:'quantidade',finish:'acabamento'}[k])+': '+(before[k]||'por indicar')+' → '+p.fields[k]).join('; '));persist();render();toast('Dados guardados. Revê as linhas do orçamento se necessário.');return}
if(form.id==='request-form'){dirty(p);event(p,'Pedido editado. Texto anterior: '+p.request,'Edição manual');p.request=f.get('request')}
if(form.id==='memory-form'){p.memory.unshift({id:uid(),text:f.get('text'),kind:f.get('kind'),source:f.get('source'),created:now()});event(p,'Registo de memória adicionado: '+f.get('text'),f.get('source'))}
if(form.id==='confirm-form'){const m=p.memory.find(m=>m.id===form.dataset.id);event(p,'Informação confirmada. Antes: '+m.text+' | Confirmado: '+f.get('text'),f.get('source'));m.text=f.get('text');m.kind='Confirmado';m.source=f.get('source');m.confirmed=now()}
if(form.id==='revision-form'){if(p.lines.length){const v=snapshot(p,'Antes da alteração');p.versions.push(v);event(p,'V'+v.number+' preservada antes da alteração.','Memória do projeto')}p.memory.unshift({id:uid(),text:'Alteração solicitada: '+f.get('text')+' — rever impacto no orçamento.',kind:'Pendente',source:f.get('source'),created:now()});event(p,'Alteração recebida: '+f.get('text'),f.get('source'));p.status='Em revisão';tab='orcamento'}
if(form.id==='line-form'){dirty(p);p.lines.push({id:uid(),desc:f.get('desc'),qty:Number(f.get('qty')),unit:f.get('unit'),price:Number(f.get('price')),source:f.get('source')});if(globalThis.forjaPilot&&String(f.get('price')).trim()==='')pilotAutoPrice(p.lines[p.lines.length-1],{withUnit:true});event(p,'Linha adicionada: '+f.get('desc'),f.get('source'))}
if(form.id==='source-form'){p.lines.find(l=>l.id===form.dataset.id).source=f.get('source');event(p,'Fonte de linha atualizada.',f.get('source'))}
if(form.id==='version-form'){const v=snapshot(p,f.get('label'));p.versions.push(v);event(p,'V'+v.number+' guardada: '+euro(calc(v).subtotal)+' sem IVA.','Orçamento');tab='versoes'}
if(form.id==='accept-form'){const v=p.versions.find(v=>v.id===form.dataset.id);v.accepted=now();v.acceptSource=f.get('source');if(JSON.stringify(v.lines)===JSON.stringify(p.lines)&&v.markup===p.markup&&v.vat===p.vat&&JSON.stringify(v.fields)===JSON.stringify(p.fields)&&v.request===p.request)p.status='Aceite';event(p,'Aceitação da V'+v.number+' registada manualmente.',f.get('source'));p.memory.unshift({id:uid(),kind:'Confirmado',text:'Cliente aceitou a V'+v.number+' por '+euro(calc(v).subtotal)+' sem IVA.',source:f.get('source'),created:now()});tab='versoes'}
closeModal();persist();render();toast('Guardado no projeto.');});
document.addEventListener('change',e=>{const el=e.target,p=project();if(el.id==='files'){addFiles(el.files);return}if(el.id==='line-unit'){if(el.value==='h')$('#line-price').value=state.settings.hour;return}if(el.dataset.line){const l=p.lines.find(l=>l.id===el.dataset.line),k=el.dataset.key;const old=l[k];if(['price','qty'].includes(k)){const n=Number(el.value);if(!Number.isFinite(n)||n<0||n>1e9){el.value=old;toast('Introduz um valor válido, igual ou superior a zero.');return}l[k]=n}else l[k]=el.value;if(old!==l[k]){if(globalThis.forjaPilot&&pilotAfterEdit(p,l,k))return;if(p.status==='Aceite'){p.status='Em revisão';const statusEl=document.querySelector('.heading .badge');if(statusEl)statusEl.textContent=p.status;}event(p,'Linha «'+l.desc+'»: '+({qty:'quantidade',price:'custo unitário',unit:'unidade',desc:'descrição'}[k])+' alterado de '+old+' para '+l[k]);persist();updateTotals()}return}if(el.id==='markup'||el.id==='vat'){const n=Number(el.value),max=el.id==='vat'?100:1000;if(!Number.isFinite(n)||n<0||n>max){el.value=p[el.id];return}const old=p[el.id];p[el.id]=n;if(p.status==='Aceite')p.status='Em revisão';event(p,(el.id==='vat'?'IVA':'Acréscimo')+' alterado de '+old+'% para '+n+'%.');persist();render()}});
document.addEventListener('input',e=>{if(e.target.id==='memory-search'){memoryQuery=e.target.value;$('#memory-items').innerHTML=memoryItems(project())}if(e.target.id==='project-search'){query=e.target.value;$('#project-rows').innerHTML=projectRows(state.projects.filter(p=>(p.name+' '+p.client+' '+p.code).toLowerCase().includes(query.toLowerCase())))}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('tr[data-action]'))e.target.click()});
function extraFieldRow(x={label:'',value:''}){return `<div class="extra-row"><input class="field" name="extra-label" maxlength="80" placeholder="Dado (ex.: Cor RAL)" value="${esc(x.label)}" aria-label="Nome do dado"><input class="field" name="extra-value" maxlength="300" placeholder="Valor (ex.: 7016 texturado)" value="${esc(x.value)}" aria-label="Valor"><button type="button" class="ghost small" data-remove-field aria-label="Remover dado">×</button></div>`}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add-field]');if(add){const box=document.querySelector('#extra-fields');if(box.children.length>=100)return toast('Até 100 dados extra.');box.insertAdjacentHTML('beforeend',extraFieldRow());box.lastElementChild.querySelector('input').focus();return}const rm=e.target.closest('[data-remove-field]');if(rm)rm.closest('.extra-row').remove()});
persist();render();
